SELECT e.id, e.is_remote AS employee_is_remote, e.manager_id AS employee_manager_id, e.hire_date AS employee_hire_date, m.is_remote AS manager_is_remote, m.email AS manager_email, m.full_name AS manager_full_name FROM employees e LEFT OUTER JOIN employees m ON e.manager_id = m.id WHERE m.full_name LIKE 'Em%' OR m.hire_date BETWEEN '2023-12-20' AND '2024-08-14' ORDER BY e.manager_id, id LIMIT 5;
